import{_ as l,C as s,o as i,c,a5 as d,E as e,j as o,a as n}from"./chunks/framework.DuVjalqf.js";const g="/rb_cobot_docs_muscat/images/program/repeat-modal.avif",h="/rb_cobot_docs_muscat/images/program/repeat-form.avif",p="/rb_cobot_docs_muscat/images/program/repeat-while.avif",T=JSON.parse('{"title":"반복","description":"","frontmatter":{"title":"반복","outline":[2,3]},"headers":[],"relativePath":"manual/program/repeat.md","filePath":"manual/program/repeat.md","lastUpdated":1792552919000}'),m={name:"manual/program/repeat.md"};function u(_,t,b,x,f,W){const r=s("DemoFrame"),a=s("ScenarioSteps");return i(),c("div",null,[t[0]||(t[0]=d('<h1 id="반복" tabindex="-1">반복 <a class="header-anchor" href="#반복" aria-label="Permalink to &quot;반복&quot;">​</a></h1><p><strong>반복</strong>은 안에 넣은 명령을 여러 번 되풀이해 실행하는 명령입니다. 같은 작업을 정해진 횟수만큼 하거나, 조건이 참인 동안 계속하고 싶을 때 사용합니다. 반복을 중간에 끝내려면 <strong>반복중단</strong>을 함께 씁니다.</p><p>이 문서에서는 <strong>프로그램</strong> 화면에서 다음을 해 봅니다.</p><ul><li>반복을 추가하고 반복 횟수 정하기</li><li>While·Do While 조건으로 반복하기</li><li>반복 안에 반복중단 넣기</li></ul><div class="tip custom-block"><p class="custom-block-title">준비</p><p>프로그램이 하나 열려 있어야 합니다. 프로그램이 없으면 <a href="/rb_cobot_docs_muscat/manual/program-create">새 프로그램 만들기</a>를 먼저 따라 합니다.</p></div><h2 id="반복-추가하기" tabindex="-1">반복 추가하기 <a class="header-anchor" href="#반복-추가하기" aria-label="Permalink to &quot;반복 추가하기&quot;">​</a></h2><p>공통 명령어에서 <strong>반복</strong>을 누르면 먼저 반복 횟수를 정하는 창이 나타납니다. 정하고 나면 트리에 반복이 추가되고, 그 아래에 반복할 명령을 넣는 <strong>빈 영역</strong>이 생깁니다.</p><p><img src="'+g+'" alt="반복 횟수 설정 창"></p><div class="tbl-nowrap-2"><table tabindex="0"><thead><tr><th style="text-align:center;">번호</th><th>항목</th><th>설명</th></tr></thead><tbody><tr><td style="text-align:center;">①</td><td><strong>직접 입력 / 무한 반복</strong></td><td><strong>직접 입력</strong>은 횟수를 숫자로 적습니다. <strong>무한 반복</strong>을 고르면 횟수 입력이 꺼지고 멈출 때까지 계속 반복합니다.</td></tr><tr><td style="text-align:center;">②</td><td><strong>횟수 입력</strong></td><td>반복할 횟수입니다. 기본값은 1이며 100을 넘는 값은 설정할 수 없습니다.</td></tr><tr><td style="text-align:center;">③</td><td><strong>취소</strong></td><td>반복을 추가하지 않고 창을 닫습니다.</td></tr><tr><td style="text-align:center;">④</td><td><strong>설정</strong></td><td>정한 횟수로 반복을 추가합니다. 트리에 <code>반복 (3 Times)</code>처럼 표시됩니다.</td></tr></tbody></table></div><h2 id="설정-화면" tabindex="-1">설정 화면 <a class="header-anchor" href="#설정-화면" aria-label="Permalink to &quot;설정 화면&quot;">​</a></h2><p>트리의 반복을 누르면 오른쪽에 설정 화면이 열립니다. 아래는 횟수 3으로 추가한 직후의 화면입니다.</p><p><img src="'+h+'" alt="반복 설정 화면"></p><div class="tbl-nowrap-2"><table tabindex="0"><thead><tr><th style="text-align:center;">번호</th><th>항목</th><th>설명</th></tr></thead><tbody><tr><td style="text-align:center;">①</td><td><strong>반복 횟수</strong></td><td>정한 횟수만큼 반복합니다.</td></tr><tr><td style="text-align:center;">②</td><td><strong>While 방식</strong></td><td>조건이 참인 동안 반복합니다. 조건은 <strong>반복할 때마다 먼저</strong> 확인하므로, 처음부터 거짓이면 한 번도 실행하지 않습니다.</td></tr><tr><td style="text-align:center;">③</td><td><strong>Do While 방식</strong></td><td>먼저 한 번 실행한 뒤 조건을 확인해, 참이면 다시 반복합니다. 조건이 처음부터 거짓이어도 <strong>한 번은 실행</strong>합니다.</td></tr><tr><td style="text-align:center;">④</td><td><strong>직접 입력 / 무한 반복</strong></td><td>반복 횟수 방식에서 횟수 입력 방식을 고릅니다.</td></tr><tr><td style="text-align:center;">⑤</td><td><strong>횟수 / 조건 입력</strong></td><td>반복 횟수 방식에서는 횟수(최대 100), While·Do While 방식에서는 조건식을 입력합니다.</td></tr><tr><td style="text-align:center;">⑥</td><td><strong>닫기</strong></td><td>설정 화면을 닫습니다. 저장하지 않은 변경이 있으면 저장하지 않고 닫을지 묻습니다.</td></tr><tr><td style="text-align:center;">⑦</td><td><strong>저장</strong></td><td>정한 방식을 적용하고 설정 화면을 닫습니다.</td></tr></tbody></table></div><p>반복 횟수 방식에서 횟수에 <strong>음수</strong>를 입력하면 무한 반복합니다. 무한 반복은 반복 안에서 반복중단을 실행하거나 프로그램을 멈출 때까지 계속됩니다.</p><h3 id="while·do-while-방식" tabindex="-1">While·Do While 방식 <a class="header-anchor" href="#while·do-while-방식" aria-label="Permalink to &quot;While·Do While 방식&quot;">​</a></h3><p>While 방식(②)이나 Do While 방식(③)을 고르면 상태 영역이 조건 입력칸으로 바뀝니다. 조건에는 앞에서 선언한 변수를 쓸 수 있는 식을 입력합니다(예: <code>count &lt; 3</code>). 아래는 While 방식에 조건을 입력한 화면입니다.</p><p><img src="'+p+'" alt="While 조건을 입력한 화면"></p><p>저장하면 트리의 반복 옆에 <code>While =&gt; count &lt; 3</code>(Do While은 <code>Do While =&gt; ...</code>)처럼 표시됩니다.</p><h2 id="반복중단" tabindex="-1">반복중단 <a class="header-anchor" href="#반복중단" aria-label="Permalink to &quot;반복중단&quot;">​</a></h2><p><strong>반복중단</strong>은 반복 안에서 실행하면 반복을 끝내고 반복 다음 명령으로 넘어가는 명령입니다. 반복 안의 빈 영역에 추가하며, 보통 <a href="/rb_cobot_docs_muscat/manual/program/if">조건문 (If)</a> 분기 안에 넣어 &quot;조건이 맞으면 반복을 끝낸다&quot;는 흐름을 만듭니다.</p><h2 id="디버그로-값-확인하기" tabindex="-1">디버그로 값 확인하기 <a class="header-anchor" href="#디버그로-값-확인하기" aria-label="Permalink to &quot;디버그로 값 확인하기&quot;">​</a></h2><p>프로그램을 실행하는 동안 변수 값이 어떻게 바뀌는지 보려면 <strong>디버그</strong> 명령을 넣습니다. 디버그는 실행을 <strong>일시 중지</strong>하고 정한 변수의 값을 팝업 창에 표시합니다. 설정 화면에서 다음을 정합니다.</p><table tabindex="0"><thead><tr><th>항목</th><th>설명</th></tr></thead><tbody><tr><td><strong>옵션</strong></td><td><strong>디버그 팝업</strong>은 변수 값을 팝업 창에 표시하고 실행을 멈춥니다. <strong>사용자 로그</strong>는 입력한 문자열을 로그에 기록하며 실행을 멈추지 않습니다.</td></tr><tr><td><strong>실행 조건</strong></td><td><strong>항상 실행</strong> 또는 <strong>UI가 사용 중일 때만 실행</strong>을 고릅니다(디버그 팝업에서만).</td></tr><tr><td><strong>정지 옵션</strong></td><td><strong>모든 작업</strong> 또는 <strong>현재 작업</strong>을 고릅니다(디버그 팝업에서만).</td></tr><tr><td><strong>변수 이름</strong></td><td>값을 보려는 변수 이름을 한 줄씩 추가합니다.</td></tr></tbody></table><p>창은 <code>Debug Variables</code>라는 제목으로 <code>변수 이름: 값</code>을 한 줄씩 보여 주며, 숫자는 소수로 표시됩니다(예: <code>1.0</code>). 창에서 <strong>Resume</strong>을 누르면 프로그램이 이어서 실행되고 <strong>Stop</strong>을 누르면 프로그램이 멈춥니다.</p><h2 id="직접-해-보기" tabindex="-1">직접 해 보기 <a class="header-anchor" href="#직접-해-보기" aria-label="Permalink to &quot;직접 해 보기&quot;">​</a></h2><p>예제 프로그램은 변수 <code>count</code>를 0으로 두고, 반복 안에서 스크립트 <code>count += 1</code>로 값을 올린 뒤 디버그로 <code>count</code>를 보여 줍니다. 실습은 세 가지이며 어느 쪽부터 해도 되고, 앞의 실습을 하지 않아도 시작할 수 있습니다. 실습을 다시 시작하면 바꾼 값은 처음 상태로 돌아갑니다.</p><h3 id="while-조건-설정하기" tabindex="-1">While 조건 설정하기 <a class="header-anchor" href="#while-조건-설정하기" aria-label="Permalink to &quot;While 조건 설정하기&quot;">​</a></h3><p>반복(3 Times)을 While 방식으로 바꾸고 조건을 입력해 저장하는 과정입니다.</p><ol><li>반복은 기본적으로 정한 횟수(3 Times)만큼 실행한다는 것을 확인합니다.</li><li>반복의 설정 화면을 열어 <strong>반복 횟수·While 방식·Do While 방식</strong>의 차이를 확인하고 <strong>While 방식</strong>을 고릅니다.</li><li>While 조건에 <code>count &lt; 3</code>을 입력하고 저장합니다. 입력한 값이 안내와 같아야 다음으로 넘어갈 수 있으며, 공백은 다르게 입력해도 같은 값으로 봅니다. 건너뛰면 자동으로 입력됩니다.</li></ol>',29)),e(r,{id:"program-repeat-while"}),t[1]||(t[1]=o("h4",{id:"사용-방법",tabindex:"-1"},[n("사용 방법 "),o("a",{class:"header-anchor",href:"#사용-방법","aria-label":'Permalink to "사용 방법"'},"​")],-1)),e(a,{id:"program-repeat-while"}),t[2]||(t[2]=d('<h3 id="반복-실행-확인하기" tabindex="-1">반복 실행 확인하기 <a class="header-anchor" href="#반복-실행-확인하기" aria-label="Permalink to &quot;반복 실행 확인하기&quot;">​</a></h3><p>While 조건(<code>count &lt; 3</code>)이 입력된 반복을 실행해 값이 바뀌는 것을 확인하는 과정입니다.</p><ol><li>재생(▶)을 누르면 프로그램이 실행됩니다.</li><li>반복할 때마다 디버그 창이 떠서 <code>count: 1.0</code>, <code>count: 2.0</code>, <code>count: 3.0</code>이 차례로 표시되고, <code>count</code>가 3이 되면 반복이 끝납니다.</li></ol>',3)),e(r,{id:"program-repeat-run"}),t[3]||(t[3]=o("h4",{id:"사용-방법-1",tabindex:"-1"},[n("사용 방법 "),o("a",{class:"header-anchor",href:"#사용-방법-1","aria-label":'Permalink to "사용 방법"'},"​")],-1)),e(a,{id:"program-repeat-run"}),t[4]||(t[4]=d('<h3 id="반복중단으로-반복-끝내기" tabindex="-1">반복중단으로 반복 끝내기 <a class="header-anchor" href="#반복중단으로-반복-끝내기" aria-label="Permalink to &quot;반복중단으로 반복 끝내기&quot;">​</a></h3><p>반복 안의 조건문(<code>count == 2</code>)에 반복중단을 넣어 반복을 도중에 끝내는 과정입니다.</p><ol><li>조건문 안의 빈 영역을 눌러 위치를 정하고 편집 아이콘으로 명령어 목록을 연 뒤 <strong>반복중단</strong>을 추가합니다.</li><li>재생(▶)을 누르고 <strong>프로그램 변경 확인</strong> 창에서 <strong>저장</strong>을 누르면 프로그램이 실행됩니다.</li><li><code>count: 1.0</code>, <code>count: 2.0</code>이 표시된 뒤 <code>count == 2</code>가 참이라 반복이 끝나고, 세 번째 창은 나타나지 않습니다.</li></ol>',3)),e(r,{id:"program-repeat-break"}),t[5]||(t[5]=o("h4",{id:"사용-방법-2",tabindex:"-1"},[n("사용 방법 "),o("a",{class:"header-anchor",href:"#사용-방법-2","aria-label":'Permalink to "사용 방법"'},"​")],-1)),e(a,{id:"program-repeat-break"})])}const P=l(m,[["render",u]]);export{T as __pageData,P as default};
